package com.mahesh.empleave.security;
import com.mahesh.empleave.user.*;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;
@Service public class JwtService { private final byte[] key; private final long expiry; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiry){this.key=secret.getBytes(StandardCharsets.UTF_8);this.expiry=expiry;} public String issue(AppUser u){return Jwts.builder().subject(u.getEmail()).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiry)).signWith(Keys.hmacShaKeyFor(key)).compact();} public String subject(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(token).getPayload().getSubject();}}
